/bin/bash -lc "python - <<'PY'
from pathlib import Path
import os,signal,json
p=Path('work/median100');alive=[]
for q in Path('/proc').iterdir():
 if not q.name.isdigit():continue
 try:
  a=(q/'cmdline').read_bytes().split(b'\\0')
  if a and a[0].split(b'/')[-1]==b'anneal' and b'median100' in b' '.join(a):alive.append(int(q.name))
 except OSError:pass
for pid in alive:os.kill(pid,signal.SIGTERM)
print(json.dumps({'matchingProcesses':alive,'action':'SIGTERM sent' if alive else 'already stopped; no matching solver process','latestSavedRound':json.loads((p/'balance.json.checkpoint.json').read_text())['round'],'savedMap':'interim_round_151_map.png','savedTransfer':'interim_round_151_transfer.json'}))
PY"
